17	
18	module MSHR(
19	  input                               clk                          ,
20	  input                               rst_n                        ,
21	  
22	  //input allocted signals
23	  input                               mshr_alloc_valid_i           ,
24	  //input alloc handshake signals
25	  input                               mshr_alloc_hit_i             ,
26	  input [`WAY_BITS-1:0]               mshr_alloc_way_i             ,
27	  input                               mshr_alloc_dirty_i           ,
28	  input                               mshr_alloc_flush_i           ,
29	  input                               mshr_alloc_last_flush_i      ,
30	  input  [`SET_BITS-1:0]              mshr_alloc_set_i             ,
31	  //input  [`L2C_BITS-1:0]              mshr_alloc_l2cidx_i          ,
32	  input  [`OP_BITS-1:0]               mshr_alloc_opcode_i          ,
33	  input  [`SIZE_BITS-1:0]             mshr_alloc_size_i            ,
34	  input  [`SOURCE_BITS-1:0]           mshr_alloc_source_i          ,
35	  input  [`TAG_BITS-1:0]              mshr_alloc_tag_i             ,
36	  input  [`OFFSET_BITS-1:0]           mshr_alloc_offset_i          ,
37	  input  [`PUT_BITS-1:0]              mshr_alloc_put_i             ,
38	  input  [`DATA_BITS-1:0]             mshr_alloc_data_i            ,
39	  input  [`MASK_BITS-1:0]             mshr_alloc_mask_i            ,
40	  input  [`PARAM_BITS-1:0]            mshr_alloc_param_i           ,
41	  
42	  //output status signals
43	  output                              mshr_status_hit_o            ,
44	  output  [`WAY_BITS-1:0]             mshr_status_way_o            ,
45	  output                              mshr_status_dirty_o          ,
46	  output                              mshr_status_flush_o          ,
47	  output                              mshr_status_last_flush_o     ,
48	  output  [`SET_BITS-1:0]             mshr_status_set_o            ,
49	  //output  [`L2C_BITS-1:0]             mshr_status_l2cidx_o         ,
50	  output  [`OP_BITS-1:0]              mshr_status_opcode_o         ,
51	  output  [`SIZE_BITS-1:0]            mshr_status_size_o           ,
52	  output  [`SOURCE_BITS-1:0]          mshr_status_source_o         ,
53	  output  [`TAG_BITS-1:0]             mshr_status_tag_o            ,
54	  output  [`OFFSET_BITS-1:0]          mshr_status_offset_o         ,
55	  output  [`PUT_BITS-1:0]             mshr_status_put_o            ,
56	  output  [`DATA_BITS-1:0]            mshr_status_data_o           ,
57	  output  [`MASK_BITS-1:0]            mshr_status_mask_o           ,
58	  output  [`PARAM_BITS-1:0]           mshr_status_param_o          ,
59	  
60	  //input valid bool
61	  input                               mshr_valid_i                 ,
62	  
63	  //input mshr_wait bool
64	  input                               mshr_wait_i                  ,
65	  
66	  //input  mixed part
67	  input                               mshr_mixed_i                 ,
68	  
69	  //output  schedule  part
70	  //schedule part a : Decoupled FullRequest
71	  input                               mshr_schedule_a_ready_i      ,
72	  output                              mshr_schedule_a_valid_o      ,
73	  //input  schedule part handshake signals
74	  output  [`SET_BITS-1:0]             mshr_schedule_a_set_o        ,
75	  //output  [`L2C_BITS-1:0]             mshr_schedule_a_l2cidx_o     ,
76	  output  [`OP_BITS-1:0]              mshr_schedule_a_opcode_o     ,
77	  output  [`SIZE_BITS-1:0]            mshr_schedule_a_size_o       ,
78	  output  [`SOURCE_BITS-1:0]          mshr_schedule_a_source_o     ,
79	  output  [`TAG_BITS-1:0]             mshr_schedule_a_tag_o        ,
80	  output  [`OFFSET_BITS-1:0]          mshr_schedule_a_offset_o     ,
81	  output  [`PUT_BITS-1:0]             mshr_schedule_a_put_o        ,
82	  output  [`DATA_BITS-1:0]            mshr_schedule_a_data_o       ,
83	  output  [`MASK_BITS-1:0]            mshr_schedule_a_mask_o       ,
84	  output  [`PARAM_BITS-1:0]           mshr_schedule_a_param_o      ,
85	  
86	  //schedule part d  : Decoupled DirectoryResult_lite
87	  input                               mshr_schedule_d_ready_i      ,
88	  output                              mshr_schedule_d_valid_o      ,
89	  //schedule part d handshake signals
90	  output                              mshr_schedule_d_hit_o        ,
91	  output  [`WAY_BITS-1:0]             mshr_schedule_d_way_o        ,
92	  output                              mshr_schedule_d_dirty_o      ,
93	  output                              mshr_schedule_d_flush_o      ,
94	  output                              mshr_schedule_d_last_flush_o ,
95	  output  [`SET_BITS-1:0]             mshr_schedule_d_set_o        ,
96	  //output  [`L2C_BITS-1:0]             mshr_schedule_d_l2cidx_o     ,
97	  output  [`OP_BITS-1:0]              mshr_schedule_d_opcode_o     ,
98	  output  [`SIZE_BITS-1:0]            mshr_schedule_d_size_o       ,
99	  output  [`SOURCE_BITS-1:0]          mshr_schedule_d_source_o     ,
100	  output  [`TAG_BITS-1:0]             mshr_schedule_d_tag_o        ,
101	  output  [`OFFSET_BITS-1:0]          mshr_schedule_d_offset_o     ,
102	  output  [`PUT_BITS-1:0]             mshr_schedule_d_put_o        ,
103	  output  [`DATA_BITS-1:0]            mshr_schedule_d_data_o       ,
104	  output  [`MASK_BITS-1:0]            mshr_schedule_d_mask_o       ,
105	  output  [`PARAM_BITS-1:0]           mshr_schedule_d_param_o      ,
106	  
107	  //schedule  data part   
108	  output  [`DATA_BITS-1:0]            mshr_schedule_data_o         ,
109	  
110	  //output  schedule dir part
111	  input                               mshr_schedule_dir_ready_i    ,
112	  output                              mshr_schedule_dir_valid_o    ,
113	  //schedule part dir handshake signals
114	  output  [`WAY_BITS-1:0]             mshr_schedule_dir_way_o      ,
115	  output  [`TAG_BITS-1:0]             mshr_schedule_dir_data_tag_o ,
116	  output  [`SET_BITS-1:0]             mshr_schedule_dir_set_o      ,
117	  
118	  //merge part
119	  input                               mshr_merge_valid_i           ,
120	  output                              mshr_merge_ready             ,
121	  //merge part handshake signals
122	  input  [`MASK_BITS-1:0]             mshr_merge_mask_i            ,
123	  input  [`DATA_BITS-1:0]             mshr_merge_data_i            ,    
124	  input  [`OP_BITS-1:0]               mshr_merge_opcode_i          ,
125	  input  [`PUT_BITS-1:0]              mshr_merge_put_i             ,
126	  input  [`SOURCE_BITS-1:0]           mshr_merge_source_i          ,
127	  
128	  //sinked part
129	  input                               mshr_sinked_valid_i          ,
130	  //sinked part handshake signals
131	  input  [`OP_BITS-1:0]               mshr_sinked_opcode_i         ,
132	  input  [`SOURCE_BITS-1:0]           mshr_sinked_source_i         ,
133	  input  [`DATA_BITS-1:0]             mshr_sinked_data_i            
134	  );
135	  parameter writeBytes       = 4             ;
136	  parameter full_mask_bytes  = 8 * writeBytes;
137	  
138	  reg                               mixed_reg                      ;
139	  reg   [`DATA_BITS-1:0]            data_reg                       ;
140	  //output status signals
141	  reg                               request_hit_reg                ;
142	  reg   [`WAY_BITS-1:0]             request_way_reg                ;
143	  reg                               request_dirty_reg              ;
144	  reg                               request_flush_reg              ;
145	  reg                               request_last_flush_reg         ;
146	  reg   [`SET_BITS-1:0]             request_set_reg                ;
147	  //reg   [`L2C_BITS-1:0]             request_l2cidx_reg             ;
148	  reg   [`OP_BITS-1:0]              request_opcode_reg             ;
149	  reg   [`SIZE_BITS-1:0]            request_size_reg               ;
150	  reg   [`SOURCE_BITS-1:0]          request_source_reg             ;
151	  reg   [`TAG_BITS-1:0]             request_tag_reg                ;
152	  reg   [`OFFSET_BITS-1:0]          request_offset_reg             ;
153	  reg   [`PUT_BITS-1:0]             request_put_reg                ;
154	  reg   [`DATA_BITS-1:0]            request_data_reg               ;
155	  reg   [`MASK_BITS-1:0]            request_mask_reg               ;
156	  reg   [`PARAM_BITS-1:0]           request_param_reg              ;
157	  
158	  wire [`DATA_BITS-1:0] full_mask;
159	  
160	  assign full_mask = {{full_mask_bytes{mshr_merge_mask_i[0]}}, {full_mask_bytes{mshr_merge_mask_i[1]}}, {full_mask_bytes{mshr_merge_mask_i[2]}}, {full_mask_bytes{mshr_merge_mask_i[3]}}};
161	  
162	  wire [`DATA_BITS-1:0] merge_data;
163	  assign merge_data = ( mshr_merge_data_i & full_mask ) | (data_reg & (~full_mask));
164	  
165	  reg sche_a_valid  ;//init to 0
166	  reg sche_dir_valid;//init to 0
167	  reg sink_d_reg    ;//init to 0
168	  
169	  
170	  //output status signals
171	  assign   mshr_status_hit_o         =      request_hit_reg        ;
172	  assign   mshr_status_way_o         =      request_way_reg        ;
173	  assign   mshr_status_dirty_o       =      request_dirty_reg      ;
174	  assign   mshr_status_flush_o       =      request_flush_reg      ;
175	  assign   mshr_status_last_flush_o  =      request_last_flush_reg ;
176	  assign   mshr_status_set_o         =      request_set_reg        ;
177	  //assign   mshr_status_l2cidx_o      =      request_l2cidx_reg     ;
178	  assign   mshr_status_opcode_o      =      request_opcode_reg     ;
179	  assign   mshr_status_size_o        =      request_size_reg       ;
180	  assign   mshr_status_source_o      =      request_source_reg     ;
181	  assign   mshr_status_tag_o         =      request_tag_reg        ;
182	  assign   mshr_status_offset_o      =      request_offset_reg     ;
183	  assign   mshr_status_put_o         =      request_put_reg        ;
184	  assign   mshr_status_data_o        =      request_data_reg       ;
185	  assign   mshr_status_mask_o        =      request_mask_reg       ;
186	  assign   mshr_status_param_o       =      request_param_reg      ;
187	  
188	  always @(posedge clk or negedge rst_n) begin
189	    if(~rst_n) 
190	      begin
191	        request_hit_reg        <= 0;
192	        request_way_reg        <= 0;
193	        request_dirty_reg      <= 0;
194	        request_flush_reg      <= 0;
195	        request_last_flush_reg <= 0;
196	        request_set_reg        <= 0;
197	  //      request_l2cidx_reg     <= 0;
198	        request_opcode_reg     <= 0;
199	        request_size_reg       <= 0;
200	        request_source_reg     <= 0;
201	        request_tag_reg        <= 0;
202	        request_offset_reg     <= 0;
203	        request_put_reg        <= 0;
204	        request_data_reg       <= 0;
205	        request_mask_reg       <= 0;
206	        request_param_reg      <= 0;
207	        sink_d_reg             <= 0;
208	      end
209	    else if(mshr_alloc_valid_i)
210	      begin
211	        request_hit_reg        <= mshr_alloc_hit_i            ;
212	        request_way_reg        <= mshr_alloc_way_i            ;
213	        request_dirty_reg      <= mshr_alloc_dirty_i          ;
214	        request_flush_reg      <= mshr_alloc_flush_i          ;
215	        request_last_flush_reg <= mshr_alloc_last_flush_i     ;
216	        request_set_reg        <= mshr_alloc_set_i            ;
217	  //      request_l2cidx_reg     <= mshr_alloc_l2cidx_i         ;
218	        request_opcode_reg     <= mshr_alloc_opcode_i         ;
219	        request_size_reg       <= mshr_alloc_size_i           ;
220	        request_source_reg     <= mshr_alloc_source_i         ;
221	        request_tag_reg        <= mshr_alloc_tag_i            ;
222	        request_offset_reg     <= mshr_alloc_offset_i         ;
223	        request_put_reg        <= mshr_alloc_put_i            ;
224	        request_data_reg       <= mshr_alloc_data_i           ;
225	        request_mask_reg       <= mshr_alloc_mask_i           ;
226	        request_param_reg      <= mshr_alloc_param_i          ;
227	        sink_d_reg             <= 0;
228	      end
229	    else if(mshr_sinked_valid_i)
230	      sink_d_reg             <= 1'b1;
231	    else
232	      begin
233	        request_hit_reg        <=         request_hit_reg        ;
234	        request_way_reg        <=         request_way_reg        ;
235	        request_dirty_reg      <=         request_dirty_reg      ;
236	        request_flush_reg      <=         request_flush_reg      ;
237	        request_last_flush_reg <=         request_last_flush_reg ;
238	        request_set_reg        <=         request_set_reg        ;
239	  //      request_l2cidx_reg     <=         request_l2cidx_reg     ;
240	        request_opcode_reg     <=         request_opcode_reg     ;
241	        request_size_reg       <=         request_size_reg       ;
242	        request_source_reg     <=         request_source_reg     ;
243	        request_tag_reg        <=         request_tag_reg        ;
244	        request_offset_reg     <=         request_offset_reg     ;
245	        request_put_reg        <=         request_put_reg        ;
246	        request_data_reg       <=         request_data_reg       ;
247	        request_mask_reg       <=         request_mask_reg       ;
248	        request_param_reg      <=         request_param_reg      ;
249	      end
250	  end
251	  
252	  always @(posedge clk or negedge rst_n) begin
253	    if(~rst_n) 
254	      begin
255	        data_reg <= 0;
256	      end
257	    else if(mshr_alloc_valid_i)
258	      begin
259	        data_reg <= mshr_alloc_data_i;
260	      end
261	    else if(mshr_merge_valid_i)
262	      begin
263	        data_reg <= merge_data;
264	      end 
265	    else if(mshr_sinked_valid_i)
266	      begin
267	        data_reg <= mshr_sinked_data_i;
268	      end
269	    else data_reg<= data_reg;
270	  end
271	  
272	  assign mshr_schedule_d_valid_o      = mshr_valid_i && sink_d_reg     ; //为了使得最后全弹出来才拉低，需要知道这个MSHR是否还有效
273	  assign mshr_schedule_d_hit_o        = 1'b0                           ;//  io.schedule.d.bits.hit := false.B
274	  assign mshr_schedule_d_way_o        = request_way_reg                ;
275	  assign mshr_schedule_d_dirty_o      = 1'b0                           ;//  io.schedule.d.bits.dirty := false.B
276	  assign mshr_schedule_d_flush_o      = request_flush_reg              ;
277	  assign mshr_schedule_d_last_flush_o = request_last_flush_reg         ;
278	  assign mshr_schedule_d_set_o        = request_set_reg                ;
279	  //assign mshr_schedule_d_l2cidx_o     = request_l2cidx_reg             ;
280	  assign mshr_schedule_d_opcode_o     = request_opcode_reg             ;
281	  assign mshr_schedule_d_size_o       = request_size_reg               ;
282	  assign mshr_schedule_d_source_o     = request_source_reg             ;
283	  assign mshr_schedule_d_tag_o        = request_tag_reg                ;
284	  assign mshr_schedule_d_offset_o     = request_offset_reg             ;
285	  assign mshr_schedule_d_put_o        = request_put_reg                ;
286	  assign mshr_schedule_d_data_o       = data_reg                       ;//io.schedule.d.bits.data := data_reg
287	  assign mshr_schedule_d_mask_o       = request_mask_reg               ;
288	  assign mshr_schedule_d_param_o      = request_param_reg              ;
289	  
290	  assign mshr_schedule_data_o         = data_reg                       ;//io.schedule.data := data_reg
291	  
292	  //process for schedule a part
293	  assign mshr_schedule_a_valid_o = sche_a_valid && !mshr_wait_i;
294	  assign mshr_schedule_a_set_o   = request_set_reg             ;
295	  assign mshr_schedule_a_opcode_o= `GET                        ;
296	  assign mshr_schedule_a_tag_o   = request_tag_reg             ;
297	  //assign mshr_schedule_a_l2cidx_o= request_l2cidx_reg        ;
298	  assign mshr_schedule_a_param_o = request_param_reg           ;
299	  assign mshr_schedule_a_put_o   = request_put_reg             ;
300	  assign mshr_schedule_a_offset_o= request_offset_reg          ;
301	  assign mshr_schedule_a_source_o= request_source_reg          ;
302	  assign mshr_schedule_a_data_o  = request_data_reg            ;
303	  assign mshr_schedule_a_size_o  = request_size_reg            ;
304	  assign mshr_schedule_a_mask_o  = {`MASK_BITS{1'b1}}          ;
305	  
306	  always @(posedge clk or negedge rst_n) begin
307	    if(~rst_n) begin
308	      sche_a_valid <= 0; 
309	    end 
310	    else if(mshr_schedule_a_valid_o && mshr_schedule_a_ready_i) begin
311	      sche_a_valid <= 1'b0;
312	    end
313	    else if (mshr_alloc_valid_i) begin
314	      sche_a_valid <= 1'b1;
315	    end
316	    else sche_a_valid <= sche_a_valid;
317	  end
318	
319	  always @(posedge clk or negedge rst_n) begin
320	    if(~rst_n) begin
321	      sche_dir_valid <= 0;  
322	    end
323	    else if(mshr_alloc_valid_i) begin
324	      sche_dir_valid <= 1'b0;
325	    end
326	    else if(mshr_schedule_dir_ready_i && mshr_schedule_dir_valid_o) begin
327	      sche_dir_valid <= 1'b0;
328	    end
329	    else if(mshr_mixed_i) begin
330	      sche_dir_valid <= 1'b0;
331	    end
332	    else if(mshr_sinked_valid_i && !(mshr_mixed_i ||mixed_reg )) begin
333	      sche_dir_valid <= 1'b1;
334	    end
335	  end
336	
337	  always @(posedge clk or negedge rst_n) begin
338	    if(~rst_n) begin
339	      mixed_reg <= 0;  
340	    end
341	    else if(mshr_alloc_valid_i) begin
342	      mixed_reg <= 1'b0;
343	    end
344	    else if(mshr_mixed_i) begin
345	      mixed_reg <= 1'b1;
346	    end
347	    else mixed_reg <= mixed_reg;
348	  end
349	  
350	  assign mshr_schedule_dir_valid_o    = sche_dir_valid && (request_opcode_reg == `GET );
351	  assign mshr_schedule_dir_set_o      = request_set_reg                                ;
352	  assign mshr_schedule_dir_data_tag_o = request_tag_reg                                ;
353	  assign mshr_schedule_dir_way_o      = request_way_reg                                ;
354	
355	endmodule
