17	
18	module Listbuffer(
19	  input                                         clk                           ,
20	  input                                         rst_n                         ,
21	  // val putbuffer, in fact it is listbuffer class
22	  output                                        List_buffer_push_ready_o      ,//data out
23	  input                                         List_buffer_push_valid_i      ,//data in
24	  input [`PUT_BITS-1:0]                         List_buffer_push_index_i      ,//data in
25	  input [`DATA_BITS-1:0]                        List_buffer_push_data_data_i  ,//data in;
26	  input [`MASK_BITS-1:0]                        List_buffer_push_data_mask_i  ,//data in;
27	  input [`PUT_BITS-1:0]                         List_buffer_push_data_put_i   ,
28	  input [`OP_BITS-1:0]                          List_buffer_push_data_opcode_i,
29	  input [`SOURCE_BITS-1:0]                      List_buffer_push_data_source_i,
30	  output [`PUTLISTS-1:0]                        List_buffer_valid_o           ,//data out
31	  input                                         List_buffer_pop_valid_i       ,//data in
32	  input [`PUT_BITS-1:0]                         List_buffer_pop_data_i        ,//data in
33	  output [`DATA_BITS-1:0]                       List_buffer_data_data_o       ,//data out
34	  output [`MASK_BITS-1:0]                       List_buffer_data_mask_o       ,//data out
35	  output [`PUT_BITS-1:0]                        List_buffer_data_put_o        ,
36	  output [`OP_BITS-1:0]                         List_buffer_data_opcode_o     ,
37	  output [`SOURCE_BITS-1:0]                     List_buffer_data_source_o         
38	  );
