548	    
549	  assign about_replace           = (dir_write_set_i == dir_result_set_o) && (dir_write_way_i == dir_result_way_o)  &&  dir_write_valid_i && dir_write_ready_o; 
550	  assign timely_hit              = (dir_read_tag_r/*dir_read_tag_i_reg_1*/ == dir_write_tag_i )&& dir_write_valid_i && dir_write_ready_o && (dir_read_set_i_reg_1 == dir_write_set_i);
551	  assign dir_read_ready_o        = ((wipeDone  && !(dir_write_valid_i && dir_write_ready_o)) || (setQuash_1 && tagmatch_1)) && !flush_issue_reg && dir_result_ready_i;   //also fire when bypass , write and read can not happen at the same time
552	  assign dir_result_valid_o      = flush_issue_reg_1 ? /*status_reg_dirty_reg_1[(NUM_WAY)*(flush_set_reg_1) +  flush_way_reg_1 ]&& flush_issue_reg_1*/1'b1 : valid_signal ;
553	  assign dir_result_hit_o        = flush_issue_reg_1 ? 1'b1 :((status_reg_valid[(dir_result_set_o)*(NUM_WAY) + dir_result_way_o] == 1'b1) ? 1'b0: ((hit || (setQuash && tagmatch && dir_result_set_o == dir_write_set_i) || timely_hit) && (!about_replace)));
554	  assign dir_result_way_o        = flush_issue_reg_1 ? flush_way_reg_1 : (hit? hitway: ((setQuash && tagmatch)?  dir_write_way_i_reg_1: (timely_hit ? dir_write_way_i :victimWay)  )) ;
555	  assign dir_result_put_o        = flush_issue_reg_1 ? 1'b0 : read_bits_reg_put ;
556	  assign dir_result_data_o       = flush_issue_reg_1 ? 0 : read_bits_reg_data ;
557	  assign dir_result_offset_o     = flush_issue_reg_1 ? 0 : read_bits_reg_offset ;
558	  assign dir_result_size_o       = flush_issue_reg_1 ? $clog2(`L2CACHE_BEATBYTES) : read_bits_reg_size ;
559	  assign dir_result_set_o        = flush_issue_reg_1 ? flush_set_reg_1 : read_bits_reg_set ;
560	  assign dir_result_source_o     = read_bits_reg_source ;
561	  //assign dir_result_source_o   = flush_issue_reg_1 ? {1'b1, : read_bits_reg_source ;
562	  assign dir_result_tag_o        = flush_issue_reg_1 ? flush_tag : read_bits_reg_tag ;
563	  assign dir_result_opcode_o     = flush_issue_reg_1 ? `HINT: read_bits_reg_opcode ;
564	  assign dir_result_mask_o       = flush_issue_reg_1 ? {`MASK_BITS{1'b1}} : read_bits_reg_mask ;
565	  assign dir_result_dirty_o      = flush_issue_reg_1 ? status_reg_dirty_reg_1[(flush_set_reg_1)*(NUM_WAY) + flush_way_reg_1 ] : (not_replace ? 0: status_reg_dirty[(set)*(NUM_WAY) + dir_result_way_o ] ) ;    
566	  assign dir_result_last_flush_o = flush_issue_reg_1 ? flushDone_reg_1 : 1'b0 ;
567	  assign dir_result_flush_o      = flush_issue_reg_1 ;
568	  assign dir_result_victim_tag_o = ways[dir_result_way_o*`TAG_BITS+:`TAG_BITS];//ways[flush_way*`TAG_BITS+:`TAG_BITS];
569	  //assign dir_result_l2cidx_o   = flush_issue_reg_1 ? 0 : read_bits_reg_l2cidx ;
570	  assign dir_result_param_o      = flush_issue_reg_1 ? 0 : read_bits_reg_param ;
571	
572	endmodule
573	
574

