        end */
    end
  always @(posedge clk or negedge rst_n) 
    begin
      if(!rst_n)
        begin
          flush_issue_reg_1      <= 0;
          flush_set_reg_1        <= 0;
          flush_way_reg_1        <= 0;
          flush_tag_reg_1        <= 0;
          flushDone_reg_1        <= 0;
