596	  //assign d_address_o = (`L2C_BITS !=0) ? {s_final_req_tag,s_final_req_l2cidx,s_final_req_set,s_final_req_offset}
597	  //                                     : {s_final_req_tag,s_final_req_set,s_final_req_offset}                                             ;
598	  assign d_address_o = {s_final_req_tag,s_final_req_set,s_final_req_offset}; //`L2C_BITS != 0;
599	  assign d_param_o   = 'd0                                                                                                                ;
600	
601	  //to sourceA(memory) //add invalid and flush
602	  assign a_valid_o   = (current_state == STAGE_4 || current_state == STAGE_7 || current_state == STAGE_3) && ((!s_final_req_hit && (s_final_req_dirty || s_final_req_opcode == `PUTFULLDATA || s_final_req_opcode == `PUTPARTIALDATA)) || ((s_final_req_opcode == `HINT) && s_final_req_dirty));
603	  assign a_set_o     = s_final_req_set                                                                                                    ;
604	  //assign a_l2cidx_o  = s_final_req_l2cidx                                                                                                 ;
605	  assign a_size_o    = s_final_req_size                                                                                                   ;
606	  assign a_source_o  = 'd4                                                                                                                ;
607	  assign a_tag_o     = s_final_req_tag                                                                                                    ;
608	  assign a_offset_o  = s_final_req_offset                                                                                                 ;
609	  assign a_put_o     = s_final_req_put                                                                                                    ;
610	  assign a_mask_o    = s_final_req_mask                                                                                                   ;
611	  assign a_param_o   = s_final_req_param                                                                                                  ;
612	  assign a_data_o    = (!s_final_req_dirty && (s_final_req_opcode == `PUTFULLDATA || s_final_req_opcode == `PUTPARTIALDATA)) ? s_final_req_data : bs_rdat_data_i;//have changed
613	  assign a_opcode_o  = `PUTFULLDATA                                                                                                       ;
614	
615	  assign finish_issue_o = d_valid_o && s_final_req_last_flush                                                                             ;
616	endmodule
